"""Format/freshness unit tests use generated bytes, not real browser evidence."""
import copy
import struct
import tempfile
import unittest
import zlib
from datetime import datetime, timedelta, timezone
from pathlib import Path

from loop_factory import ROOT, make_packet
from uxloop.evidence import Evidence
from uxloop.io import GateStop, digest, sha


class EvidenceTests(unittest.TestCase):
    def setUp(self):
        (ROOT / '.ux-loop').mkdir(exist_ok=True)
        self.temp = tempfile.TemporaryDirectory(dir=ROOT / '.ux-loop')
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.packet = make_packet(self.root)

    def test_live_format_rejects_synthetic_svg(self):
        self.packet['mode'] = 'live'
        for artifact in self.packet['artifacts']:
            artifact['created_at'] = datetime.now(timezone.utc).isoformat()
        with self.assertRaisesRegex(GateStop, 'must be PNG'):
            Evidence(self.packet, self.root).screenshot('artifact-reference', self.packet['scenarios'][0]['viewport'])

    def test_png_crc_dimensions_and_truncation_are_checked(self):
        def chunk(kind, raw):
            return struct.pack('>I', len(raw)) + kind + raw + struct.pack('>I', zlib.crc32(kind + raw) & 0xffffffff)
        raw = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', 390, 844, 8, 2, 0, 0, 0))
        raw += chunk(b'IDAT', zlib.compress((b'\0' + b'\xff' * (390 * 3)) * 844)) + chunk(b'IEND', b'')
        artifact = next(x for x in self.packet['artifacts'] if x['id'] == 'artifact-reference')
        target = self.root / artifact['path']
        target.write_bytes(raw)
        artifact['sha256'] = sha(raw)
        evidence = Evidence(self.packet, self.root)
        viewport = self.packet['scenarios'][0]['viewport']
        evidence.screenshot(artifact['id'], viewport)
        with self.assertRaisesRegex(GateStop, 'wrong-size'):
            evidence.screenshot(artifact['id'], {**viewport, 'width': 400})
        for damaged in [raw[:-1], raw[:40] + bytes([raw[40] ^ 1]) + raw[41:]]:
            target.write_bytes(damaged)
            artifact['sha256'] = sha(damaged)
            with self.assertRaisesRegex(GateStop, 'Corrupt'):
                evidence.screenshot(artifact['id'], viewport)

    def test_live_evidence_must_be_fresh_and_not_from_future(self):
        self.packet['mode'] = 'live'
        artifact = self.packet['artifacts'][0]
        for delta in [timedelta(days=-8), timedelta(hours=1)]:
            artifact['created_at'] = (datetime.now(timezone.utc) + delta).isoformat()
            with self.assertRaisesRegex(GateStop, 'freshness'):
                Evidence(self.packet, self.root).artifact(artifact['id'])

    def test_live_replay_cannot_predate_actual_code_fix(self):
        self.packet['mode'] = 'live'
        with self.assertRaisesRegex(GateStop, 'predates the last code change'):
            Evidence(self.packet, self.root).browser('replay-1', self.packet['fixes'][0]['after_revision'], True,
                                                   {'read_only': {}}, '2026-09-14T00:10:00+00:00')

    def test_live_test_data_action_requires_prior_explicit_grant(self):
        self.packet['mode'] = 'live'
        scenario = self.packet['scenarios'][0]
        scenario['steps'][0]['requires'] = 'test_data_write'
        for run in self.packet['browser_runs']:
            run['scenario_digest'] = digest(scenario)
        evidence = Evidence(self.packet, self.root)
        run = self.packet['browser_runs'][0]
        for grants, message in [({'read_only': {}}, 'ungranted'),
                                 ({'read_only': {}, 'test_data_write': {'at': '2026-09-14T00:10:00+00:00'}}, 'not granted before')]:
            with self.assertRaisesRegex(GateStop, message):
                evidence.browser(run['id'], run['code_revision'], False, grants)


if __name__ == '__main__':
    unittest.main()
